"use strict";

const http = require("http");
const https = require("https");

function codeOf(error) {
  return String(error && (error.autojs6Code || error.code || error.name || ""));
}

function syncCode(action) {
  try {
    action();
    return "allowed";
  } catch (error) {
    return codeOf(error);
  }
}

exports.probe = async function probe(ctx) {
  const before = ctx.requestCount();
  const httpCode = syncCode(() => http.request("http://example.invalid/proxy-denied", {
    proxy: { host: "127.0.0.1", port: 8080 },
  }));
  const httpsCode = syncCode(() => https.request("https://example.invalid/proxy-url-denied", {
    proxyUrl: "http://127.0.0.1:8080",
  }));
  const after = ctx.requestCount();
  return "httpnpm.proxy-denial=" + [httpCode, httpsCode, "dispatch=" + (after - before)].join("|");
};
